const KEY='ancient-manager-v1';let page='home',search='',roleFilter='',clubFilter='',selectedBracket=null,S;
const $=id=>document.getElementById(id),cash=n=>'$'+Math.round(n).toLocaleString('en-US'),clamp=(n,a=0,b=100)=>Math.min(b,Math.max(a,n)),avg=a=>a.reduce((s,n)=>s+n,0)/(a.length||1),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rng(){S.seed=(S.seed*1664525+1013904223)>>>0;return S.seed/4294967296}function int(a,b){return Math.floor(rng()*(b-a+1))+a}function date(day=S.day){return new Date(Date.UTC(2026,9,15)+day*86400000).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})}function my(){return S.teams[S.club]}function roster(t=my()){return S.players.filter(p=>p.team===t.id&&p.active).sort((a,b)=>a.role-b.role)}function owned(){return S.players.filter(p=>p.team===S.club)}function wage(){return owned().reduce((n,p)=>n+p.salary,0)+S.coach*120}function value(p){return Math.round((p.skill-50)**2*390*(1+(p.potential-p.skill)/100)/1000)*1000}function log(t){S.news.unshift({day:S.day,text:t});S.news=S.news.slice(0,70)}function money(n,t){S.budget+=n;S.ledger.unshift({day:S.day,n,text:t});S.ledger=S.ledger.slice(0,100)}function save(){try{localStorage.setItem(KEY,JSON.stringify(S));$('saveStatus').textContent='Прогресс сохранён'}catch(e){$('saveStatus').textContent='Хранилище недоступно — экспортируй карьеру'}}function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').style.display='none',3800)}
function startingBudget(club){return 1500000}
function fresh(club=0){selectedBracket=null;S={v:1,seed:Math.floor(Math.random()*4294967296),day:0,club,budget:startingBudget(club),chem:76,coach:75,facility:1,tactic:'balanced',training:'balanced',players:[],teams:[],ledger:[],news:[],events:[],history:[],active:null,wins:0,losses:0,trophies:0,prizes:0};SEED_TEAMS.forEach((t,id)=>{S.teams.push({id,name:t[0],short:t[1],region:t[2],coach:t[5],tactic:['late','balanced','tempo'][id%3],points:0});t[3].forEach((name,i)=>S.players.push({id:S.players.length,name,role:i,team:id,active:true,skill:t[4][i],potential:Math.min(99,t[4][i]+int(2,8)),form:int(70,88),morale:int(75,90),fatigue:int(5,15),salary:Math.round((t[4][i]-50)*230),contract:365}))});for(let i=0;i<5;i++)academy(null,i);S.events=[{id:0,name:'Ancient Autumn Cup',day:5,pool:250000,real:false},{id:1,name:'BLAST SLAM IX',day:36,pool:750000,real:true,url:'https://blast.tv/dota/tournaments/blast-slam-ix',range:'20–29 ноября 2026'},{id:2,name:'DreamLeague Season 30',day:48,pool:750000,real:true,url:'https://pro.eslgaming.com/tour/2026/09/introducing-dotas-ept-season-26-27/',range:'2–13 декабря 2026'},{id:3,name:'Ancient Winter Masters',day:70,pool:1000000,real:false}];ensureTournamentCalendar();log('Совет директоров: цель — выиграть турнир. Трансферный бюджет: '+cash(S.budget)+'. Добро пожаловать в '+my().name+'.');save();render()}
function academy(team,role){let id=S.players.length,skill=int(66,76);S.players.push({id,name:'Academy '+(id+1),role,team,active:team!==null,skill,potential:int(83,96),form:75,morale:80,fatigue:4,salary:3000,contract:365,fiction:true});return S.players.at(-1)}
function metric(k,t=my()){return Math.round(avg(roster(t).map(p=>p[k])))}function strength(t=my()){let own=t.id===S.club;return avg(roster(t).map(p=>p.skill*.65+p.form*.15+p.morale*.1+(100-p.fatigue)*.1))+(own?S.chem:80)*.08+(own?S.coach:80)*.04}function nextEvent(){ensureTournamentCalendar();return S.events.find(e=>e.id===S.active?.event)||S.events.find(e=>!e.done)}function locked(){return !!S.active}function stat(label,val,sub){return `<div class="stat"><label>${label}</label><strong>${val}</strong><small>${sub}</small></div>`}function bar(label,n){return `<div class="health-row"><div><span>${label}</span><b>${Math.round(n)}%</b></div><div class="bar"><b style="width:${clamp(n)}%;${n<40?'background:#f2b775':''}"></b></div></div>`}function head(k,title,desc,right=''){return `<div class="title-row"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}function btn(label,action,primary=false,disabled=false){return `<button ${disabled?'disabled':''} class="${primary?'primary':''}" onclick="${action}">${label}</button>`}function teamDisplay(t){return `<div class="team-display"><div class="crest">${t.short}</div>${t.name}</div>`}function go(p){if(page==='match'&&p!=='match'&&typeof pauseLive4==='function')pauseLive4(false);page=p;render()}function openModal(html){if(typeof pauseLive4==='function')pauseLive4(false);$('modal').innerHTML=html;$('modal').showModal()}function closeModal(){$('modal').close()}
function render(){save();$('club').innerHTML=esc(my().name)+`<small>${my().region} · Главный тренер: ${my().coach}</small>`;$('date').textContent=date();$('crumb').textContent=PAGES.find(p=>p[0]===page)?.[2]||(page==='match'?'Матч-центр':'');$('nav').innerHTML=PAGES.map(p=>`<button class="${p[0]===page?'active':''}" onclick="go('${p[0]}')"><i>${p[1]}</i>${p[2]}</button>`).join('');$('advance').textContent=S.active?'В матч-центр →':nextEvent()?.day<=S.day?'Начать турнир →':'Следующий день →';$('app').innerHTML=({home,squad,development:typeof developmentView21==='function'?developmentView21:home,menu21:typeof menuView21==='function'?menuView21:home,tactics,market,calendar,players:typeof playersView20==='function'?playersView20:home,player:typeof playerView20==='function'?playerView20:home,trophies:typeof trophiesView20==='function'?trophiesView20:home,bracket:bracketView,clubs,saves:savesView,finance,history,settings,reshuffles:reshufflesViewV1,patch:patchViewV1,practice:typeof practiceView13==='function'?practiceView13:home,ranking:typeof rankingView13==='function'?rankingView13:home,pools:heroPoolsView4,model:modelView4,match:matchView}[page]||home)()}
function home(){let e=nextEvent(),a=S.active,opp=a?S.teams[a.opponent]:null;return head('СЕЗОН 2026 / 27','Клуб строится вокруг решений.','Реальные пулы. Последовательные события. Твоя история.',`<span class="tag">● Менеджер ${my().short}</span>`)+`<div class="stats">${stat('Бюджет клуба',cash(S.budget),'Стартовый капитал: '+cash(startingBudget(S.club)))}${stat('Сила состава',Math.round(strength()),'Мастерство, форма и подготовка')}${stat('Победы / поражения',S.wins+' / '+S.losses,'Серии в твоей карьере')}${stat('Трофеи',S.trophies,'Цель совета: первый титул')}</div><div class="columns"><section class="panel hero"><div class="section-head"><div class="eyebrow">${a?'СЕЙЧАС НА СЕРВЕРЕ':'СЛЕДУЮЩИЙ ВЫЗОВ'}</div><span class="tag dim">${e.real?'Реальный турнир':'Вымышленный турнир'}</span></div><h2>${e.name}</h2><div class="matchup">${teamDisplay(my())}<div class="versus"><strong>${a?a.score.join(' : '):'VS'}</strong>${a?'BO'+(isFinal(a)?5:3):date(e.day)}</div>${opp?teamDisplay(opp):'<div class="team-display"><div class="crest">?</div>Жеребьёвка впереди</div>'}</div><div class="hero-foot"><span>Призовой фонд <b class="green">${cash(e.pool)}</b></span>${btn(a?'Открыть матч →':e.day<=S.day?'Начать турнир →':'Подготовить команду →',a?"go('match')":e.day<=S.day?'startEvent()':"go('tactics')",true)}</div></section><section class="panel"><h2>Пульс команды <span class="green">↗</span></h2>${bar('Сыгранность',S.chem)}${bar('Мораль',metric('morale'))}${bar('Игровая форма',metric('form'))}${bar('Энергия',100-metric('fatigue'))}<span class="sub">Баланс тренировок и отдыха влияет на каждую карту.</span></section></div><div class="columns"><section class="panel"><div class="section-head"><h2>Основной состав</h2><button class="text-btn" onclick="go('squad')">Управлять →</button></div>${playerTable(roster(),false)}</section><section class="panel"><h2>Новости клуба</h2>${S.news.slice(0,4).map(n=>`<div class="news"><small>${date(n.day)}</small>${esc(n.text)}</div>`).join('')}</section></div>`}
function playerTable(ps,actions=true){return `<div class="table-wrap"><table><thead><tr><th>ИГРОК</th><th>ПОЗИЦИЯ</th><th>OVR</th><th>ФОРМА</th><th>ЭНЕРГИЯ</th>${actions?'<th>КОНТРАКТ</th><th></th>':''}</tr></thead><tbody>${ps.map(p=>`<tr><td><span class="avatar">${esc(p.name.slice(0,2))}</span><b>${esc(p.name)}</b>${p.fiction?'<span class="sub">Вымышленный воспитанник</span>':''}</td><td>${ROLES[p.role]}</td><td><span class="rating">${Math.round(p.skill)}</span></td><td>${Math.round(p.form)}</td><td class="${p.fatigue>60?'red':'green'}">${Math.round(100-p.fatigue)}%</td>${actions?`<td>${cash(p.salary)}/нед.<span class="sub">${p.contract} дней · потенциал ${p.potential}</span></td><td>${btn('Профиль',`profile(${p.id})`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function squad(){return head('ЛЮДИ РЕШАЮТ','Твоя пятёрка','Пять ролей. Одна цель. Трансферы доступны между турнирами.')+`<div class="panel"><h2>Основной состав</h2>${playerTable(roster())}</div><div class="panel" style="margin-top:20px"><h2>Скамейка запасных · ${owned().filter(p=>!p.active).length}/3</h2>${owned().some(p=>!p.active)?playerTable(owned().filter(p=>!p.active)):'<p>Подпиши игрока на рынке: он попадёт в резерв. Затем переведи его в основу на своей позиции.</p>'}</div>`}
function profile(id){let p=S.players[id];openModal(`<div class="eyebrow">${ROLES[p.role]} / ${p.active?'ОСНОВА':'РЕЗЕРВ'}</div><h1>${esc(p.name)}</h1><p>Игровая оценка: ${Math.round(p.skill)} · потенциал: ${p.potential}</p>${bar('Форма',p.form)}${bar('Мораль',p.morale)}${bar('Энергия',100-p.fatigue)}<p>Стоимость: ${cash(value(p))}<br>Зарплата: ${cash(p.salary)}/неделю · контракт: ${p.contract} дней</p><div class="actions">${btn('Закрыть','closeModal()')}${!p.active?btn('Продать за '+cash(saleValue(p)),`sell(${id})`,false,locked()):''}${!p.active?btn('В основу',`promote(${id})`,true,locked()):''}${btn('Продлить · '+cash(p.salary*3),`renew(${id})`,false,S.budget<p.salary*3)}</div>`)}
function promote(id){if(locked())return;let p=S.players[id];if(p.team!==S.club||p.active)return;roster().find(x=>x.role===p.role).active=false;p.active=true;S.chem=clamp(S.chem-8);log(p.name+' переведён в основной состав. Сыгранность −8.');closeModal();render()}
function saleValue(p){return Math.round(Math.min(value(p),p.paid??value(p))*.75)}
function sell(id){if(locked())return;let p=S.players[id];if(p.team!==S.club||p.active)return;money(saleValue(p),'Продажа: '+p.name);p.team=(S.club+1)%S.teams.length;log(p.name+' покинул клуб.');closeModal();render()}
function renew(id){let p=S.players[id],cost=p.salary*3;if(p.team!==S.club||S.budget<cost)return;money(-cost,'Продление: '+p.name);p.contract+=365;p.morale=clamp(p.morale+5);closeModal();render();toast('Контракт продлён на 365 дней')}
const TACTICS={balanced:['Баланс','Драфт с балансом контроля, урона и сноса строений.'],tempo:['Ранний темп','Приоритет ранней силы и героев, способных давить строения.'],teamfight:['Командные драки','Приоритет инициации, контроля и сочетаний для командного боя.'],late:['Игра через керри','Приоритет масштабирования керри; пространство для его фарма создаётся приказами на карте.']};
function tactics(){return head('ПОДГОТОВКА К ПОБЕДЕ','Игровой план','Каждое решение меняет вероятность победы, но не гарантирует результат.')+`<h2>Стратегия на карту</h2><div class="choices">${Object.entries(TACTICS).map(([k,v])=>`<button class="choice ${S.tactic===k?'selected':''}" ${S.active?.live?'disabled':''} onclick="setTactic('${k}')"><span class="green">${S.tactic===k?'●':'○'}</span> ${v[0]}<small>${v[1]}</small></button>`).join('')}</div><h2>Режим подготовки</h2><div class="choices">${[['balanced','Сбалансированный','Форма +0,5; усталость −3; сыгранность +0,4/день.'],['intensive','Интенсивный','Форма +1,5; усталость +5; навык растёт быстрее.'],['rest','Восстановление','Усталость −12; мораль +2; форма −0,5/день.']].map(([k,v,d])=>`<button ${locked()?'disabled':''} class="choice ${S.training===k?'selected':''}" onclick="S.training='${k}';render()">${v}<small>${d}</small></button>`).join('')}</div><div class="notice">Драфт автоматически создаётся заново для каждой карты: отдельные пики и баны обеих команд. Посмотреть его можно в матч-центре.</div><div class="notice">В бою учитываются мастерство, комфорт выбранного героя, форма, мораль, энергия, предметы, уровни и готовность способностей. Драфт задаёт сильные стороны, а приказы управляют поведением команды на карте.</div>`}
function market(){let ps=S.players.filter(p=>!p.retired&&p.team!==S.club&&(!search||p.name.toLowerCase().includes(search.toLowerCase())||p.name==='Paparazi'&&['paparazzi','eurus'].some(a=>a.includes(search.toLowerCase())))&&(roleFilter===''||p.role===+roleFilter)&&(clubFilter===''||String(p.team)===clubFilter)).sort((a,b)=>b.skill-a.skill);return head('ТРАНСФЕРНЫЙ РЫНОК','Следующее усиление','Все стоимости, потенциал и зарплаты — оценки симулятора.',`<span class="tag">${cash(S.budget)}</span>`)+`<div class="filters"><input aria-label="Поиск игрока" placeholder="Найти игрока…" value="${esc(search)}" oninput="search=this.value;refreshMarket()" id="search"><select aria-label="Позиция" onchange="roleFilter=this.value;render()"><option value="">Все позиции</option>${ROLES.map((r,i)=>`<option value="${i}" ${roleFilter===String(i)?'selected':''}>${r}</option>`).join('')}</select><select aria-label="Клуб" onchange="clubFilter=this.value;render()"><option value="">Все клубы</option><option value="null" ${clubFilter==='null'?'selected':''}>Свободные агенты</option>${S.teams.filter(t=>t.id!==S.club).map(t=>`<option value="${t.id}" ${clubFilter===String(t.id)?'selected':''}>${t.name}</option>`).join('')}</select></div>${locked()?'<div class="notice">Состав заблокирован до завершения турнира.</div>':''}<div class="cards">${ps.map(p=>`<article class="panel player-card"><div class="top"><span class="tag dim">${ROLES[p.role]}</span><span class="rating">${Math.round(p.skill)}</span></div><h3>${esc(p.name)}</h3><span class="sub">${p.team===null?'Свободный агент':S.teams[p.team].name}${p.fiction?' · вымышленный':''}</span><div class="metric-grid"><div><span>Потенциал</span><b>${p.potential}</b></div><div><span>Форма</span><b>${Math.round(p.form)}</b></div><div><span>Трансфер</span><b>${cash(p.team===null?value(p)*.15:value(p))}</b></div><div><span>Зарплата/нед.</span><b>${cash(Math.round(p.salary*1.1))}</b></div></div>${btn('Обсудить контракт →',`offer(${p.id})`,false,locked())}</article>`).join('')||'<div class="empty">Игроки не найдены</div>'}</div>`}
function refreshMarket(){let el=$('search'),pos=el.selectionStart;$('app').innerHTML=market();$('search').focus();$('search').setSelectionRange(pos,pos)}
function offer(id){if(locked())return;let p=S.players[id],fee=Math.round(p.team===null?value(p)*.15:value(p)),sal=Math.round(p.salary*1.1);openModal(`<div class="eyebrow">ТРАНСФЕРНОЕ ПРЕДЛОЖЕНИЕ</div><h1>${esc(p.name)}</h1><p>Клуб согласен на переход по оценочной цене. Игрок просит повышение зарплаты на 10% и годовой контракт.</p><div class="stats" style="grid-template-columns:1fr 1fr">${stat('Стоимость перехода',cash(fee),p.team===null?'Подписной бонус':'Выплата предыдущему клубу')}${stat('Зарплата',cash(sal),'Каждую игровую неделю')}</div><p>После сделки: ${cash(S.budget-fee)}. Игрок попадёт в резерв; замена основы проводится в разделе «Состав».</p>${owned().filter(x=>!x.active).length>=3?'<p class="red">Резерв заполнен: сначала продай одного игрока.</p>':''}<div class="actions">${btn('Отмена','closeModal()')}${btn('Подписать',`buy(${id})`,true,S.budget<fee||owned().filter(x=>!x.active).length>=3)}</div>`)}
function buy(id){let p=S.players[id],fee=Math.round(p.team===null?value(p)*.15:value(p));if(locked()||p.team===S.club||S.budget<fee||owned().filter(x=>!x.active).length>=3)return;if(p.team!==null&&p.active)academy(p.team,p.role);money(-fee,'Трансфер: '+p.name);p.team=S.club;p.paid=fee;p.active=false;p.salary=Math.round(p.salary*1.1);p.contract=365;log('Подписан '+p.name+' за '+cash(fee)+'.');closeModal();render();toast('Контракт подписан. Игрок в резерве.')}
function tick(){S.day++;let mode=S.training;owned().forEach(p=>{p.contract--;p.fatigue=clamp(p.fatigue+(mode==='intensive'?5:mode==='rest'?-12:-3));p.form=clamp(p.form+(mode==='intensive'?1.5:mode==='rest'?-.5:.5),30,99);p.morale=clamp(p.morale+(mode==='rest'?2:mode==='intensive'?-.3:.2));if(mode!=='rest')p.skill=Math.min(p.potential,p.skill+(mode==='intensive'?.055:.025)*S.facility);if(p.contract<=0){money(-p.salary*4,'Автопродление: '+p.name);p.contract=180;log('Контракт '+p.name+' продлён автоматически на 180 дней за '+cash(p.salary*4)+'.')}});S.chem=clamp(S.chem+(mode==='rest'?.2:.4));if(S.day%7===0){money(65000+S.trophies*5000,'Недельный спонсорский платёж');money(-wage(),'Зарплаты игроков и штаба');money(-S.facility*6000,'База и операционные расходы');if(S.budget<0){money(500000,'Экстренный взнос совета');S.chem=clamp(S.chem-15);owned().forEach(p=>p.morale=clamp(p.morale-15));log('Дефицит бюджета. Совет внёс $500 000; мораль и сыгранность −15.')}}if(S.day%10===0){let p=roster()[int(0,4)];p.form=clamp(p.form+3);log(p.name+' отлично сыграл на тренировках. Форма +3.')}}
function advance(){if(S.active){go('match');return}if(nextEvent().day<=S.day){startEvent();return}tick();render()}
function skip(){if(S.active)return;while(S.day<nextEvent().day)tick();render();toast('Команда прибыла на турнир')}
function startEvent(){let e=nextEvent();if(S.active||e.day>S.day)return;let ids=S.teams.map(t=>t.id).filter(id=>id!==S.club);for(let i=ids.length-1;i>0;i--){let j=int(0,i);[ids[i],ids[j]]=[ids[j],ids[i]]}let entrants=[S.club,...ids],groups=[];for(let g=0;g<4;g++){let teams=entrants.slice(g*4,g*4+4);groups.push({name:String.fromCharCode(65+g),teams,matches:[],seeds:Object.fromEntries(teams.map(id=>[id,strength(S.teams[id])]))})}e.entrants=entrants;e.groups=groups;e.format='groups-v1';S.active={event:e.id,phase:'groups',groupDay:0,groups,round:0,totalRounds:3,pairs:[],bracket:[],opponent:groupPairs(groups[0],0).find(p=>p.includes(S.club)).find(id=>id!==S.club),score:[0,0],maps:[],live:null,seriesDone:false};selectedBracket=e.id;tournamentTab='groups';log('Начался '+e.name+': 4 группы по 4 команды. Две лучшие команды каждой группы выйдут в плей-офф.');go('bracket')}
function finishSeries(){let a=S.active;if(!a?.seriesDone)return;if(a.phase==='groups'){finishGroupSeries();return}let total=a.totalRounds||3,won=a.score[0]>a.score[1],winners=[];let roundResults=a.pairs.map(pair=>{let own=pair.includes(S.club),sim=own?null:simulateSeries(pair,a.round===total-1),winner=own?(won?S.club:a.opponent):sim.winner;winners.push(winner);let score=own?(pair[0]===S.club?a.score:[...a.score].reverse()).join(':'):sim.score;return {pair,winner,score}});a.bracket.push(roundResults);if(won&&a.round<total-1){a.round++;a.pairs=[];for(let i=0;i<winners.length;i+=2)a.pairs.push([winners[i],winners[i+1]]);a.opponent=a.pairs.find(p=>p.includes(S.club)).find(id=>id!==S.club);a.score=[0,0];a.maps=[];a.live=null;a.seriesDone=false;tick();selectedBracket=a.event;go('bracket');return}let place=won?1:2**(total-a.round-1)+1,e=nextEvent();let shares={1:.4,2:.2,3:.1,5:.04,9:.005},reward=Math.round(e.pool*(shares[place]||.005));while(winners.length>1){let results=[],next=[];for(let i=0;i<winners.length;i+=2){let pair=[winners[i],winners[i+1]],sim=simulateSeries(pair,winners.length===2),winner=sim.winner;next.push(winner);results.push({pair,winner,score:sim.score})}a.bracket.push(results);winners=next}e.done=true;e.place=place;e.reward=reward;e.bracket=a.bracket;e.champion=winners[0];e.totalRounds=total;money(reward,e.name+' · '+placeLabel(place));S.prizes+=reward;if(place===1)S.trophies++;S.teams[e.champion].points+=100;my().points+=place===1?0:place===2?60:place===3?30:place===5?10:5;log(e.name+': '+placeLabel(place)+', призовые '+cash(reward)+'. Чемпион — '+S.teams[e.champion].name+'.');selectedBracket=e.id;S.active=null;ensureTournamentCalendar();go('bracket');toast('Турнир завершён. Призовые зачислены.')}

function showBracket(id){selectedBracket=id;go('bracket')}
function finance(){let out=wage()+S.facility*6000,inc=65000+S.trophies*5000;return head('ЭКОНОМИКА КЛУБА','Каждый доллар работает','Платежи списываются раз в 7 игровых дней. Никаких реальных покупок.')+`<div class="stats">${stat('На счету',cash(S.budget),'Доступно для трансферов и развития')}${stat('Доход / неделю',cash(inc),'Спонсор + $5 000 за каждый трофей')}${stat('Расход / неделю',cash(out),'Игроки, штаб, база')}${stat('Баланс / неделю',cash(inc-out),'Без трансферов и призовых')}</div><div class="columns"><section class="panel"><h2>Тренировочная база · уровень ${S.facility}/5</h2><p>Каждый уровень ускоряет развитие мастерства. Содержание: ${cash(S.facility*6000)}/неделю.</p>${btn('Улучшить · '+cash(S.facility*150000),'upgradeBase()',true,S.facility>=5||S.budget<S.facility*150000)}</section><section class="panel"><h2>Тренерский штаб · ${S.coach}/95</h2><p>Расширение штаба: +5 к качеству тренера и +$600 к недельным расходам.</p>${btn('Расширить · $100 000','upgradeCoach()',false,S.coach>=95||S.budget<100000)}</section></div><div class="panel"><h2>Движение средств</h2><div class="table-wrap"><table><thead><tr><th>ДАТА</th><th>ОПЕРАЦИЯ</th><th>СУММА</th></tr></thead><tbody>${S.ledger.map(l=>`<tr><td>${date(l.day)}</td><td>${esc(l.text)}</td><td class="${l.n>=0?'green':'red'}">${l.n>=0?'+':''}${cash(l.n)}</td></tr>`).join('')||'<tr><td colspan="3">Пока нет операций. Начальный капитал — $1 500 000.</td></tr>'}</tbody></table></div></div>`}
function upgradeBase(){let cost=S.facility*150000;if(S.facility>=5||S.budget<cost)return;money(-cost,'Улучшение тренировочной базы');S.facility++;render();toast('База улучшена')}
function upgradeCoach(){if(S.coach>=95||S.budget<100000)return;money(-100000,'Расширение тренерского штаба');S.coach+=5;render()}
function history(){return head('ИСТОРИЯ КАРЬЕРЫ','Каждая серия имеет значение','Результаты и подробные отчёты сохраняются в этом браузере.')+`<div class="panel">${S.history.length?S.history.map((h,i)=>`<div class="round"><span class="tag ${h.win?'':'dim'}">${h.win?'ПОБЕДА':'ПОРАЖЕНИЕ'}</span> <b>${my().short} ${h.score.join(' : ')} ${h.opponent}</b><p>${h.event}${h.stage?' · '+h.stage:''} · ${date(h.day)}</p>${btn('Отчёт по картам',`report(${i})`)}</div>`).join(''):'<div class="empty">Твоя история ещё не написана. Сыграй первую серию.</div>'}</div>`}
function report(i){let h=S.history[i];openModal(`<h2>${my().name} — ${h.opponent}</h2>${h.maps.map((m,j)=>`<div class="round"><strong>Карта ${j+1} · ${m.win?'Победа':'Поражение'}</strong><p>${m.duration} мин · ${m.kills}:${m.deaths} · ${TACTICS[m.tactic][0]}</p>${m.decisions?.length?'<h3>Твои решения</h3>'+m.decisions.map(d=>'<div class="news">'+d.minute+':00 · '+esc(d.title)+'</div>').join(''):''}${m.players.map(p=>`<div class="news">${esc(p.name)} · ${p.hero} <b>${p.k}/${p.d}/${p.a}</b></div>`).join('')}</div>`).join('')}<div class="actions">${btn('Закрыть','closeModal()')}</div>`)}
function settings(){return head('ТВОЯ КАРЬЕРА','Настройки и происхождение данных','Срез составов: 15 октября 2026. После старта мир развивается по правилам игры.')+`<div class="columns"><section class="panel"><h2>Сохранение</h2>${btn('Открыть 5 слотов сохранения',"go('saves')",true)}<p>Автосохранение работает на этом устройстве в этом браузере. Для переноса скачай JSON и импортируй его на другом устройстве.</p>${btn('Экспорт карьеры','exportSave()',true)}<label class="form-label">Импорт сохранения<input type="file" accept=".json,application/json" style="display:block;margin-top:10px;max-width:100%" onchange="importSave(this.files[0])"></label></section><section class="panel"><h2>Новая карьера</h2><p>Выбери любой из 16 клубов. У всех стартовый бюджет $1,5 млн. Текущая карьера будет заменена после подтверждения.</p><select id="newClub">${S.teams.filter(t=>!t.fiction).map(t=>`<option value="${t.id}" ${t.id===S.club?'selected':''}>${t.name}</option>`).join('')}</select> ${btn('Начать заново','confirmReset()')}</section></div><section class="panel sources"><h2>Что настоящее, а что моделируется</h2><p>Имена и стартовые составы взяты из доступных публикаций о сезоне 2026/27. Это ручной срез, а не подключение к живой базе. Шестнадцать клубов включены в игровую лигу; её участие в реальных событиях вымышлено. Если публикация устарела или ошиблась, состав может отличаться от официальной регистрации.</p><p>Рейтинги, потенциал, форма, мораль, усталость, зарплаты, трансферные цены и контракты придуманы для баланса. Они не являются оценкой реального здоровья игроков или достоверными финансовыми данными. Игроки и клубы с пометкой «вымышленный» созданы для карьеры; их имена можно менять. После ухода игрока соперник сначала подписывает свободного агента нужной роли; при отсутствии кандидатов появляется вымышленный игрок. Участие всех клубов в турнирах, сетки и распределение призовых адаптированы. Добавленные сезоны PGL WALLACHIA, BLAST SLAM, DREAMLEAGUE, THE INTERNATIONAL, ESL ONE и FISSURE — игровая модель. Их даты, места проведения и призовые не являются анонсами организаторов; подробности отмечены в календаре.</p><a href="https://www.gosugamers.net/dota2/news/79066-dota-2-post-the-international-2026-roster-shuffle-tracker" target="_blank" rel="noopener">GosuGamers — перестановки, XG, OG, LGD, Tidebound, PlayTime ↗</a><a href="https://esport.vision/team/team-spirit" target="_blank" rel="noopener">Team Spirit — состав и роли ↗</a><a href="https://cyberscore.live/en/teams/team-yandex/" target="_blank" rel="noopener">Team Yandex — состав ↗</a><a href="https://dotesports.com/dota-2/news/betboom-team-torontotokyo-coach-save-mid" target="_blank" rel="noopener">BetBoom Team — перестановки ↗</a><a href="https://blast.tv/dota/tournaments/blast-slam-ix" target="_blank" rel="noopener">BLAST SLAM IX — официальные даты ↗</a><a href="https://pro.eslgaming.com/tour/2026/09/introducing-dotas-ept-season-26-27/" target="_blank" rel="noopener">ESL — календарь и фонд DreamLeague 30 ↗</a><a href="https://parivision.gg/teams/dota-2/" target="_blank" rel="noopener">PARIVISION — официальный состав ↗</a><a href="https://navi.gg/en/teams/dota2" target="_blank" rel="noopener">NAVI — официальный состав ↗</a><a href="https://cyberscore.live/en/teams/1win-team/" target="_blank" rel="noopener">1w Team — состав ↗</a><a href="https://www.gosugamers.net/dota2/news/79183-aurora-gaming-bench-nightfall-to-make-way-for-skiter-as-new-carry" target="_blank" rel="noopener">Aurora — состав после смены керри ↗</a><a href="https://ggscore.com/en/dota-2/team/gamerlegion" target="_blank" rel="noopener">GamerLegion — состав ↗</a><a href="https://cyberscore.live/en/news/former-og-coach-343-joins-xipto-esports/" target="_blank" rel="noopener">Xipto — состав и тренер ↗</a><a href="https://cyberscore.live/en/teams/team-liquid/" target="_blank" rel="noopener">Team Liquid — турнирный состав с MidOne (стендин) ↗</a><a href="https://esport.vision/news/the-rosters-for-the-new-teams-at-pgl-wallachia-season-9-have-been-announced" target="_blank" rel="noopener">Conventus Stellarum — состав ↗</a><p>Malrine добавлен в Team Liquid с рейтингом 95 по настройке карьеры v1.0; это игровое изменение состава. Отдельный состав Tundra не дублируется: в доступных источниках его игроки перешли в 1w Team.</p><p>Ancient Manager — независимый фанатский проект. Не связан с Valve или перечисленными организациями.</p></section>`}
function confirmReset(){let id=+$('newClub').value;openModal(`<h2>Начать карьеру за ${S.teams[id].name}?</h2><p>Текущий прогресс будет заменён. Его можно предварительно экспортировать.</p><div class="actions">${btn('Отмена','closeModal()')}${btn('Начать',`resetWithBackup(${id})`,true)}</div>`)}
function exportSave(){let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ancient-manager-career.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function safeStrings(x){if(typeof x==='string')return !/[<>"]/g.test(x)&&(!x.startsWith('javascript:'));if(Array.isArray(x))return x.every(safeStrings);if(x&&typeof x==='object')return Object.values(x).every(safeStrings);return true}
function validSave(x){return safeStrings(x)&&x&&x.v===1&&Number.isInteger(x.club)&&x.club>=0&&Array.isArray(x.teams)&&x.club<x.teams.length&&Number.isInteger(x.day)&&x.day>=0&&Number.isFinite(x.budget)&&Array.isArray(x.teams)&&[8,16].includes(x.teams.length)&&Array.isArray(x.players)&&x.players.length<=2000&&x.players.every((p,i)=>p.id===i&&typeof p.name==='string'&&p.name.length<100&&Number.isInteger(p.role)&&p.role>=0&&p.role<5&&(p.team===null||Number.isInteger(p.team)&&p.team>=0&&p.team<x.teams.length)&&['skill','potential','form','morale','fatigue','salary','contract'].every(k=>Number.isFinite(p[k])))&&x.teams.every((t,i)=>t.id===i&&[0,1,2,3,4].every(r=>x.players.filter(p=>p.team===i&&p.active&&p.role===r).length===1))&&Array.isArray(x.events)&&x.events.length>0&&Array.isArray(x.history)&&Array.isArray(x.news)&&Array.isArray(x.ledger)&&Object.keys(TACTICS).includes(x.tactic)&&['balanced','rest','intensive'].includes(x.training)&&['seed','chem','coach','facility','wins','losses','trophies','prizes'].every(k=>Number.isFinite(x[k]))}
async function importSave(file){if(!file)return;if(file.size>5000000){toast('Файл слишком большой');return}try{let x=JSON.parse(await file.text());if(!validSave(x))throw Error();openModal(`<h2>Загрузить карьеру?</h2><p>Текущий прогресс будет заменён.</p><div class="actions">${btn('Отмена','closeModal()')}<button class="primary" id="confirmImport">Загрузить</button></div>`);$('confirmImport').onclick=()=>{if(!backupCurrent())return;S=x;migrate();selectedBracket=null;closeModal();go('home');toast('Карьера загружена')}}catch(e){toast('Не удалось прочитать сохранение. Нужен JSON Ancient Manager.')}}
function isFinal(a=S.active){return a.phase!=='groups'&&a.round===(a.totalRounds||3)-1}
function roundTitle(i,total){return ({1:'Гранд-финал',2:'Полуфинал',3:'Четвертьфинал',4:'1/8 финала'})[total-i]||'Раунд '+(i+1)}
function placeLabel(n){return n<=2?n+' место':n+'–'+((n-1)*2)+' место'}
function aiScore(firstWins,final){let need=final?3:2,loser=int(0,need-1);return (firstWins?[need,loser]:[loser,need]).join(':')}
function migrateCareerV3(){
  ensureTournamentCalendar();
  if(S.teams.length<SEED_TEAMS.length){
    try{if(!localStorage.getItem('ancient-manager-before-update'))localStorage.setItem('ancient-manager-before-update',JSON.stringify({name:'До расширения лиги',updatedAt:new Date().toISOString(),state:S}))}catch(e){}
    for(let id=S.teams.length;id<SEED_TEAMS.length;id++){
      let t=SEED_TEAMS[id];S.teams.push({id,name:t[0],short:t[1],region:t[2],coach:t[5],tactic:['late','balanced','tempo'][id%3],points:0});
      t[3].forEach((name,role)=>{let skill=t[4][role];S.players.push({id:S.players.length,name,role,team:id,active:true,skill,potential:Math.min(99,skill+5),form:80,morale:84,fatigue:10,salary:Math.round((skill-50)*230),contract:365})});
    }
    log('Лига расширена до 16 клубов. Текущие контракты, трансферы и результаты сохранены.');
  }
  delete S.draft;
  if(S.active&&S.active.phase!=='groups'&&!S.active.totalRounds)S.active.totalRounds=Math.log2((S.active.bracket[0]?.length||S.active.pairs.length*2**S.active.round)*2);
}
function knockoutView(){
  let available=S.events.filter(e=>e.done||S.active?.event===e.id);
  let id=selectedBracket??S.active?.event??available.at(-1)?.id;
  let e=available.find(e=>e.id===id)||available.at(-1);
  if(!e)return head('ТУРНИРНЫЙ ЦЕНТР','Сетка турнира','Здесь появятся все пары сразу после жеребьёвки.')+'<section class="panel empty"><h2>Жеребьёвка ещё не состоялась</h2><p>Начни ближайший турнир во вкладке «Турниры».</p>'+btn('К турнирам',"go('calendar')",true)+'</section>';
  let a=S.active?.event===e.id?S.active:null,total=a?.totalRounds||e.totalRounds||e.bracket.length,rounds=structuredClone(a?a.bracket:e.bracket);
  if(a)rounds[a.round]=a.pairs.map(pair=>{let own=pair.includes(S.club);return {pair,winner:own&&a.seriesDone?(a.score[0]>a.score[1]?S.club:a.opponent):null,score:own?(pair[0]===S.club?a.score:[...a.score].reverse()).join(':'):'—',live:own,done:own&&a.seriesDone}});
  let firstCount=rounds[0].length,stages=[];
  for(let r=0;r<total;r++){
    let count=firstCount/2**r,matches=[];
    for(let j=0;j<count;j++){
      let m=rounds[r]?.[j];
      if(!m){let prev=rounds[r-1];m={pair:[prev?.[j*2]?.winner??null,prev?.[j*2+1]?.winner??null],score:'—'}}
      let scores=m.score?.split(':')||[],status=m.live?(m.done?'Серия завершена':'Твой матч'):m.winner!=null?'Завершён':'Ожидает';
      let rows=m.pair.map((tid,k)=>`<div class="bracket-team ${tid===S.club?'your-team':''} ${m.winner===tid&&tid!=null?'winner':''}"><span>${tid==null?'<span class="unknown">Победитель пары '+(j*2+k+1)+'</span>':esc(S.teams[tid].name)}</span><b>${scores[k]??'–'}</b></div>`).join('');
      matches.push(`<article class="bracket-match ${m.live?'live-match':''}"><div class="bracket-caption"><span>Пара ${j+1} · ${r===total-1?'BO5':'BO3'}</span><span>${status}</span></div>${rows}${m.live?`<button class="bracket-play" onclick="go('match')">${m.done?'Подвести итог серии':'В матч-центр'} →</button>`:''}</article>`);
    }
    stages.push(`<section class="bracket-stage"><h3>${roundTitle(r,total)}<span>${count} ${count===1?'серия':'серии'}</span></h3><div class="bracket-matches">${matches.join('')}</div></section>`);
  }
  return head('ТУРНИРНЫЙ ЦЕНТР','Сетка турнира',e.name,`<span class="tag">${e.done?'Завершён':'Идёт турнир'} · ${firstCount*2} команд</span>`)+`<div class="filters"><label for="bracketSelect" class="sub">Выбрать турнир</label><select id="bracketSelect" onchange="selectedBracket=+this.value;render()">${available.map(v=>`<option value="${v.id}" ${v.id===e.id?'selected':''}>${esc(v.name)}${v.done?' · завершён':''}</option>`).join('')}</select>${a?btn('Мой матч →',"go('match')",true):`<span class="tag">Чемпион: ${esc(S.teams[e.champion].name)}</span>`}</div><div class="notice">Твоя команда выделена зелёным. Сетка обновляется после каждой карты; результаты остальных пар — при завершении твоей серии. На телефоне сетку можно листать вправо.</div><div class="bracket-scroll" tabindex="0" aria-label="Турнирная сетка"><div class="bracket-board" style="--matches:${firstCount}">${stages.join('')}</div></div>${e.done?`<div class="panel" style="margin-top:20px"><h2>${placeLabel(e.place)} · ${cash(e.reward)}</h2><p>Призовые уже зачислены на счёт клуба.</p>${btn('К следующему турниру',"go('calendar')",true)}</div>`:''}`;
}
function clubs(){return head('МИР DOTA 2',S.teams.length+' клубов. Одна арена.','Изучи составы соперников или найди усиление для своей команды.')+`<div class="cards">${S.teams.map(t=>`<article class="panel club-card"><div class="section-head"><span class="crest small-crest">${esc(t.short)}</span><span class="rating">${Math.round(strength(t))}</span></div><h2>${esc(t.name)}</h2><span class="tag dim">${esc(t.region)}${t.id===S.club?' · твой клуб':''}</span><p>Тренер: ${esc(t.coach)}</p>${roster(t).map(p=>`<div class="club-player"><span class="sub">${ROLES[p.role]}</span><b>${esc(p.name)}</b><span class="green">${Math.round(p.skill)}</span></div>`).join('')}${t.id===15?'<span class="sub">Стартовая настройка v1.0: Malrine · мид · 95.</span>':''}<div style="margin-top:18px">${t.id===S.club?btn('Управлять составом',"go('squad')"):btn('Игроки на рынке',`clubFilter='${t.id}';search='';roleFilter='';go('market')`)}</div></article>`).join('')}</div>`}
function slotKey(i){return 'ancient-manager-slot-'+i}
function readSnapshot(key){try{let x=JSON.parse(localStorage.getItem(key));return x&&validSave(x.state)?x:null}catch(e){return null}}
function backupCurrent(){try{localStorage.setItem('ancient-manager-backup',JSON.stringify({name:'Перед сменой карьеры',updatedAt:new Date().toISOString(),state:S}));return true}catch(e){toast('Не удалось создать резервную копию. Экспортируй карьеру в JSON.');return false}}
function resetWithBackup(id){if(!backupCurrent())return;closeModal();fresh(id);go('home')}
function saveDate(v){return new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' МСК'}
function snapshotCard(x,label,actions){return `<section class="panel save-card"><div class="section-head"><span class="tag dim">${label}</span><span class="sub">${x?saveDate(x.updatedAt):'Свободен'}</span></div><h2>${x?esc(x.name):'Пустой слот'}</h2>${x?`<p>${esc(x.state.teams[x.state.club].name)} · ${date(x.state.day)}<br>${cash(x.state.budget)} · ${x.state.wins} побед · ${x.state.trophies} трофеев${x.state.active?.live?'<br><span class="green">Пауза '+x.state.active.live.minute+':00 · карта '+(x.state.active.maps.length+1)+'</span>':x.state.active?'<br><span class="green">Во время турнира</span>':''}</p>`:'<p>Сохрани сюда текущую карьеру, чтобы вернуться к ней позже.</p>'}<div class="save-actions">${actions}</div></section>`}
function savesView(){let backup=readSnapshot('ancient-manager-backup'),legacy=readSnapshot('ancient-manager-before-update');return head('ПРОГРЕСС ПОД КОНТРОЛЕМ','Сохранения карьеры','5 ручных слотов, автосохранение и резервная копия.')+`<div class="notice">Сохранения находятся в этом браузере на этом устройстве. Автосохранение продолжает работать после каждого действия. Для переноса на другое устройство используй экспорт JSON.</div><div class="cards">${Array.from({length:5},(_,i)=>{let x=readSnapshot(slotKey(i));return snapshotCard(x,'Слот '+(i+1),btn(x?'Перезаписать':'Сохранить сюда',`askSaveSlot(${i})`,true)+(x?btn('Загрузить',`askLoad('${slotKey(i)}')`)+btn('Удалить',`askDeleteSlot(${i})`):''))}).join('')}${backup?snapshotCard(backup,'Резервная копия',btn('Восстановить',"askLoad('ancient-manager-backup')")):''}${legacy?snapshotCard(legacy,'До обновления',btn('Восстановить',"askLoad('ancient-manager-before-update')")):''}</div><div class="panel" style="margin-top:22px"><div class="section-head"><h2>Состояние автосохранения</h2><span class="tag">● Текущая карьера</span></div><p>${esc(my().name)} · ${date()} · ${cash(S.budget)}. При следующем открытии сайта эта карьера загрузится автоматически. Ручной слот сохраняет отдельную копию и не меняется при продолжении игры.</p><div class="filters">${btn('Скачать JSON','exportSave()',true)}<label class="file-button">Импортировать JSON<input type="file" accept=".json,application/json" onchange="importSave(this.files[0]);this.value=''" aria-label="Импорт сохранения"></label></div></div>`}
function askSaveSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;let x=readSnapshot(slotKey(i));openModal(`<div class="eyebrow">СЛОТ ${i+1}</div><h2>${x?'Перезаписать сохранение?':'Сохранить карьеру'}</h2><p>${x?'Предыдущее сохранение в этом слоте будет заменено.':'Можно загрузить эту копию на любом этапе карьеры.'}</p><label class="form-label" for="slotName">Название сохранения</label><input id="slotName" maxlength="60" value="${esc(x?.name||my().name+' · '+date())}" style="width:100%"><div class="actions">${btn('Отмена','closeModal()')}${btn('Сохранить',`writeSlot(${i})`,true)}</div>`)}
function writeSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;let name=$('slotName').value.trim().slice(0,60)||'Сохранение '+(i+1);try{localStorage.setItem(slotKey(i),JSON.stringify({name,updatedAt:new Date().toISOString(),state:S}));closeModal();go('saves');toast('Карьера сохранена в слот '+(i+1))}catch(e){toast('Не удалось сохранить: хранилище браузера недоступно или заполнено. Скачай JSON.')}}
function askLoad(key){let x=readSnapshot(key);if(!x){toast('Сохранение повреждено или недоступно');return}openModal(`<h2>Загрузить «${esc(x.name)}»?</h2><p>${esc(x.state.teams[x.state.club].name)} · ${date(x.state.day)}<br>Текущая карьера будет помещена в резервную копию.</p><div class="actions">${btn('Отмена','closeModal()')}<button id="confirmLoad" class="primary">Загрузить</button></div>`);$('confirmLoad').onclick=()=>{let next=structuredClone(x.state);if(!backupCurrent())return;S=next;migrate();selectedBracket=S.active?.event??null;closeModal();go(S.active?'bracket':'home');toast('Карьера загружена')}}
function askDeleteSlot(i){let x=readSnapshot(slotKey(i));if(!x)return;openModal(`<h2>Удалить слот ${i+1}?</h2><p>«${esc(x.name)}» будет удалено. Текущая карьера продолжится.</p><div class="actions">${btn('Отмена','closeModal()')}<button id="confirmDelete" class="primary">Удалить</button></div>`);$('confirmDelete').onclick=()=>{try{localStorage.removeItem(slotKey(i));closeModal();go('saves');toast('Слот очищен')}catch(e){toast('Не удалось удалить сохранение')}}}

let tournamentTab='groups';
function groupPairs(g,day){let [a,b,c,d]=g.teams;return [[[a,d],[b,c]],[[a,c],[d,b]],[[a,b],[c,d]]][day]}
function standings(g){let rows=g.teams.map(id=>({id,played:0,w:0,l:0,mf:0,ma:0,points:0}));for(let m of g.matches){let [x,y]=m.pair.map(id=>rows.find(r=>r.id===id)),[a,b]=m.score.split(':').map(Number);x.played++;y.played++;x.mf+=a;x.ma+=b;y.mf+=b;y.ma+=a;let w=m.winner===x.id?x:y,l=w===x?y:x;w.w++;w.points+=3;l.l++}return rows.sort((a,b)=>b.points-a.points||(b.mf-b.ma)-(a.mf-a.ma)||b.mf-a.mf||(g.seeds[b.id]-g.seeds[a.id])||a.id-b.id)}
function finishGroupSeries(){let a=S.active,e=nextEvent();if(!a?.seriesDone||a.phase!=='groups')return;for(let g of a.groups)for(let pair of groupPairs(g,a.groupDay)){let match=pair.includes(S.club)?{pair,winner:a.score[0]>a.score[1]?S.club:a.opponent,score:(pair[0]===S.club?a.score:[...a.score].reverse()).join(':')}:simulateSeries(pair);g.matches.push({...match,day:a.groupDay})}e.groups=a.groups;if(a.groupDay<2){a.groupDay++;let ownGroup=a.groups.find(g=>g.teams.includes(S.club));a.opponent=groupPairs(ownGroup,a.groupDay).find(p=>p.includes(S.club)).find(id=>id!==S.club);a.score=[0,0];a.maps=[];a.live=null;a.seriesDone=false;tick();tournamentTab='groups';go('bracket');return}let top=a.groups.map(g=>standings(g).slice(0,2).map(r=>r.id)),entrants=[top[0][0],top[1][1],top[2][0],top[3][1],top[1][0],top[0][1],top[3][0],top[2][1]],pairs=[];for(let i=0;i<entrants.length;i+=2)pairs.push([entrants[i],entrants[i+1]]);a.phase='playoffs';a.pairs=pairs;a.round=0;a.totalRounds=3;a.bracket=[];a.live=null;a.maps=[];a.score=[0,0];a.seriesDone=false;e.playoffEntrants=entrants;if(!entrants.includes(S.club)){let bracket=[],current=pairs;while(current.length){let results=current.map(pair=>{let sim=simulateSeries(pair,current.length===1);return {pair,winner:sim.winner,score:sim.score}});bracket.push(results);let winners=results.map(m=>m.winner);if(winners.length===1){e.bracket=bracket;e.totalRounds=3;endGroupElimination(e,winners[0]);break}current=[];for(let i=0;i<winners.length;i+=2)current.push([winners[i],winners[i+1]])}return}a.opponent=pairs.find(p=>p.includes(S.club)).find(id=>id!==S.club);log('Групповой этап завершён. '+my().name+' выходит в четвертьфинал.');tick();tournamentTab='playoffs';go('bracket')}
function endGroupElimination(e,champion){e.done=true;e.place=9;e.reward=Math.round(e.pool*.005);e.champion=champion;money(e.reward,e.name+' · 9–16 место');S.prizes+=e.reward;my().points+=5;S.teams[champion].points+=100;log('Групповой этап '+e.name+': команда не вышла в плей-офф. Призовые '+cash(e.reward)+'.');S.active=null;selectedBracket=e.id;ensureTournamentCalendar();tournamentTab='groups';go('bracket');toast('Турнир завершён: 9–16 место.')}
function groupsHTML(e,a){return `<div class="notice">Каждый играет с каждым, BO3. Победа в серии — 3 очка. По 2 команды из каждой группы выходят в плей-офф. При равенстве: разница карт, выигранные карты, сила на старте турнира, ID клуба.</div><div class="group-grid">${e.groups.map(g=>{let rows=standings(g);return `<section class="panel"><h2>Группа ${g.name} <span class="tag dim">${g.matches.length}/6 серий</span></h2><div class="table-wrap"><table><thead><tr><th># / КОМАНДА</th><th>И</th><th>В–П</th><th>КАРТЫ</th><th>ОЧКИ</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.id===S.club?'own-row':''}"><td><span class="${i<2?'green':''}">${i+1}</span> ${esc(S.teams[r.id].name)}</td><td>${r.played}</td><td>${r.w}–${r.l}</td><td>${r.mf}:${r.ma}</td><td><b>${r.points}</b></td></tr>`).join('')}</tbody></table></div><div class="group-matches">${[0,1,2].map(day=>`<h3>Тур ${day+1}</h3>${groupPairs(g,day).map(pair=>{let m=g.matches.find(m=>m.day===day&&m.pair[0]===pair[0]&&m.pair[1]===pair[1]),live=a?.phase==='groups'&&a.groupDay===day&&pair.includes(S.club),score=m?.score||(live?(pair[0]===S.club?a.score:[...a.score].reverse()).join(':'):'–');return `<div class="group-match ${live?'green':''}"><span>${esc(S.teams[pair[0]].short)}</span><b>${score}</b><span>${esc(S.teams[pair[1]].short)}</span>${live?`<button onclick="go('match')">Матч →</button>`:''}</div>`}).join('')}`).join('')}</div></section>`}).join('')}</div>`}
function bracketView(){let available=S.events.filter(e=>e.done||S.active?.event===e.id),id=selectedBracket??S.active?.event??available.at(-1)?.id,e=available.find(e=>e.id===id)||available.at(-1);if(!e||!e.groups)return knockoutView();let a=S.active?.event===e.id?S.active:null;let intro=head('ТУРНИРНЫЙ ЦЕНТР',e.name,a?.phase==='groups'?'Групповой этап · тур '+(a.groupDay+1)+'/3':e.done?'Турнир завершён':'Плей-офф',a?btn('Мой матч →',"go('match')",true):`<span class="tag">Чемпион: ${esc(S.teams[e.champion].name)}</span>`);let tabs=`<div class="filters"><select aria-label="Турнир" onchange="selectedBracket=+this.value;render()">${available.map(v=>`<option value="${v.id}" ${v.id===e.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><button class="${tournamentTab==='groups'?'primary':''}" onclick="tournamentTab='groups';render()">Группы</button><button class="${tournamentTab==='playoffs'?'primary':''}" onclick="tournamentTab='playoffs';render()">Плей-офф</button></div>`;if(tournamentTab==='groups')return intro+tabs+groupsHTML(e,a);if(a?.phase==='groups')return intro+tabs+'<section class="panel empty"><h2>Плей-офф впереди</h2><p>После трёх туров сюда выйдут по две команды из каждой группы. Четвертьфиналы: A1–B2, C1–D2, B1–A2, D1–C2.</p></section>';return tabs+knockoutView()}

const STORAGE_KEYS=[KEY,KEY+'-previous','ancient-manager-backup','ancient-manager-before-update','ancient-manager-unreadable','ancient-manager-ti-start','ancient-manager-before-ti-rewind',...Array.from({length:5},(_,i)=>slotKey(i))];
let DB=null,STORE_CACHE=new Map(),MEMORY_BACKUP=null,saveQueue=Promise.resolve(),saveSerial=0,lastAuto='',storageHealth='Проверяем хранилище…',recoveryBlocked=false,slotBusy=false;
function packetStamp(raw){try{return Date.parse(JSON.parse(raw)?.updatedAt)||0}catch(e){return 0}}
function checksum(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function makePacket(state,name){let copy=JSON.parse(JSON.stringify(state));return {format:'AncientManager3',name,updatedAt:new Date().toISOString(),checksum:checksum(JSON.stringify(copy)),state:copy}}
function decodePacket(raw){try{let x=typeof raw==='string'?JSON.parse(raw):raw;if(x?.state){if(x.checksum&&checksum(JSON.stringify(x.state))!==x.checksum)return null;return validSave(x.state)?x:null}return validSave(x)?{name:'Карьера',updatedAt:new Date(0).toISOString(),state:x}:null}catch(e){return null}}
function openSaveDB(){return new Promise(resolve=>{if(typeof indexedDB==='undefined'){resolve(null);return}let expired=false;let timer=setTimeout(()=>{expired=true;resolve(null)},3000);try{let req=indexedDB.open('ancient-manager-careers',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('saves'))req.result.createObjectStore('saves')};req.onsuccess=()=>{clearTimeout(timer);if(expired){req.result.close();return}let db=req.result;db.onversionchange=()=>db.close();resolve(db)};req.onerror=()=>{clearTimeout(timer);resolve(null)};req.onblocked=()=>{clearTimeout(timer);resolve(null)}}catch(e){clearTimeout(timer);resolve(null)}})}
function dbRead(key){return new Promise(resolve=>{if(!DB){resolve(null);return}let done=false,timer;const finish=value=>{if(done)return;done=true;clearTimeout(timer);resolve(value)};timer=setTimeout(()=>finish(null),1500);try{let r=DB.transaction('saves','readonly').objectStore('saves').get(key);r.onsuccess=()=>finish(r.result??null);r.onerror=()=>finish(null)}catch(e){finish(null)}})}
function dbWrite(key,raw){return new Promise(resolve=>{if(!DB){resolve(false);return}let done=false,timer;const finish=value=>{if(done)return;done=true;clearTimeout(timer);resolve(value)};timer=setTimeout(()=>finish(false),2000);try{let tx=DB.transaction('saves','readwrite');tx.objectStore('saves').put(raw,key);tx.oncomplete=async()=>finish(await dbRead(key)===raw);tx.onerror=tx.onabort=()=>finish(false)}catch(e){finish(false)}})}
async function persist(key,raw){let local=false;try{localStorage.setItem(key,raw);local=localStorage.getItem(key)===raw}catch(e){}let indexed=await dbWrite(key,raw);if(local||indexed)STORE_CACHE.set(key,raw);return {ok:local||indexed,local,indexed}}
function paintStorageStatus(){$('saveStatus').textContent=storageHealth;let el=$('storageWarning');if(el){el.hidden=!storageHealth.includes('не подтверждено');el.innerHTML='Браузер не подтвердил запись карьеры. '+btn('Файл / код','portableSave()',true)}}
function healthText(r){return r.local&&r.indexed?'Запись подтверждена · 2 хранилища':r.indexed?'Запись подтверждена · IndexedDB':r.local?'Запись подтверждена · браузер':'Сохранение не подтверждено — скачай файл или код'}
async function initStorage(){DB=await openSaveDB();await Promise.all(STORAGE_KEYS.map(async key=>{let local=null;try{local=localStorage.getItem(key)}catch(e){}let indexed=await dbRead(key);let usable=v=>{if(decodePacket(v))return true;try{return JSON.parse(v)?.deleted===true}catch(e){return false}};let best=!local?indexed:!indexed?local:usable(local)&&!usable(indexed)?local:usable(indexed)&&!usable(local)?indexed:packetStamp(indexed)>packetStamp(local)?indexed:local;if(best)STORE_CACHE.set(key,best)}))}
function readSnapshot(key){if(key==='ancient-manager-backup'&&MEMORY_BACKUP)return MEMORY_BACKUP;let raw=STORE_CACHE.get(key);if(!raw){try{raw=localStorage.getItem(key)}catch(e){}}return decodePacket(raw)}
function save(){if(!S||recoveryBlocked)return saveQueue;let current=JSON.stringify(S);if(current===lastAuto)return saveQueue;lastAuto=current;let n=++saveSerial,packet=makePacket(S,'Автосохранение'),raw=JSON.stringify(packet);$('saveStatus').textContent='Сохраняем…';saveQueue=saveQueue.catch(()=>{}).then(async()=>{let previous=STORE_CACHE.get(KEY);if(previous&&previous!==raw&&decodePacket(previous))await persist(KEY+'-previous',previous);let result=await persist(KEY,raw);if(n===saveSerial){storageHealth=healthText(result);paintStorageStatus();if(!result.ok)lastAuto=''}return result}).catch(()=>{lastAuto='';storageHealth='Сохранение не подтверждено — скачай JSON';paintStorageStatus()});return saveQueue}
async function backupCurrent(){MEMORY_BACKUP=makePacket(S,'Перед сменой карьеры');await saveQueue;let r=await persist('ancient-manager-backup',JSON.stringify(MEMORY_BACKUP));if(r.ok)MEMORY_BACKUP=null;return r.ok}
async function resetWithBackup(id){await backupCurrent();recoveryBlocked=false;lastAuto='';closeModal();fresh(id);go('home')}
function writeSlot(i){if(slotBusy||!Number.isInteger(i)||i<0||i>4)return;let name=$('slotName').value.trim().slice(0,60)||'Сохранение '+(i+1),packet=makePacket(S,name);slotBusy=true;let button=$('slotConfirm');if(button){button.disabled=true;button.textContent='Проверяем запись…'}return (async()=>{await saveQueue;let result=await persist(slotKey(i),JSON.stringify(packet));slotBusy=false;if(result.ok&&readSnapshot(slotKey(i))?.checksum===packet.checksum){closeModal();go('saves');toast('Слот '+(i+1)+' сохранён. Чтение проверено.')}else{openModal(`<h2>Браузер не подтвердил сохранение</h2><p>Не закрывай эту вкладку. Скачай файл карьеры или скопируй код: их можно загрузить позже независимо от хранилища браузера.</p><div class="actions">${btn('Закрыть','closeModal()')}${btn('Файл или код','portableSave()',true)}</div>`)}return result})()}
function askSaveSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;let x=readSnapshot(slotKey(i));openModal(`<div class="eyebrow">СЛОТ ${i+1}</div><h2>${x?'Перезаписать сохранение?':'Сохранить карьеру'}</h2><p>После записи игра проверит, что карьеру можно прочитать обратно.</p><label class="form-label" for="slotName">Название</label><input id="slotName" maxlength="60" value="${esc(x?.name||my().name+' · '+date())}" style="width:100%"><div class="actions">${btn('Отмена','closeModal()')}<button class="primary" id="slotConfirm" onclick="writeSlot(${i})">Сохранить и проверить</button></div>`)}
function prepareLoad(x){if(!x||!validSave(x.state)){toast('Файл не распознан или повреждён');return}openModal(`<h2>Загрузить «${esc(x.name||'Карьера')}»?</h2><p>${esc(x.state.teams[x.state.club].name)} · ${date(x.state.day)}${x.state.active?.live?'<br>Пауза матча: '+x.state.active.live.minute+':00':''}<br>Текущая карьера попадёт в резервную копию. Если запись запрещена браузером, эта копия будет доступна только до закрытия вкладки.</p><div class="actions">${btn('Отмена','closeModal()')}<button id="confirmLoad" class="primary">Загрузить</button></div>`);$('confirmLoad').onclick=async()=>{if(slotBusy)return;slotBusy=true;let next=structuredClone(x.state);await backupCurrent();S=next;migrate();selectedBracket=S.active?.event??null;tournamentTab=S.active?.phase==='groups'?'groups':'playoffs';recoveryBlocked=false;lastAuto='';closeModal();go(S.active?.live?'match':S.active?'bracket':'home');await saveQueue;slotBusy=false;toast('Карьера загружена'+(S.active?.live?' на паузе '+S.active.live.minute+':00':''))}}
function askLoad(key){let x=readSnapshot(key);if(!x){toast('Сохранение недоступно или повреждено');return}prepareLoad(x)}
function askDeleteSlot(i){let x=readSnapshot(slotKey(i));if(!x)return;openModal(`<h2>Удалить слот ${i+1}?</h2><p>Текущая карьера продолжится.</p><div class="actions">${btn('Отмена','closeModal()')}<button id="confirmDelete" class="primary">Удалить</button></div>`);$('confirmDelete').onclick=async()=>{let r=await persist(slotKey(i),JSON.stringify({deleted:true,updatedAt:new Date().toISOString()}));if(r.ok){closeModal();go('saves');toast('Слот очищен')}else toast('Браузер не подтвердил удаление')}}
function downloadCareer(){let packet=makePacket(S,my().name+' · '+date()),blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ancient-manager-'+S.day+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Файл передан браузеру. Проверь загрузки или приложение «Файлы».')}
function exportSave(){portableSave()}
function portableSave(){let code=JSON.stringify(makePacket(S,my().name+' · '+date()));openModal(`<h2>Карьера с собой</h2><p>Файл и код содержат весь прогресс, включая текущую паузу карты. Их можно импортировать в другом браузере.</p><div class="filters">${btn('Скачать JSON','downloadCareer()',true)}${btn('Скопировать код','copyCareerCode()')}</div><label class="form-label" for="careerCode">Код сохранения · можно выделить и скопировать вручную</label><textarea id="careerCode" readonly spellcheck="false" rows="6" style="width:100%"></textarea><div class="actions">${btn('Закрыть','closeModal()')}</div>`);$('careerCode').value=code}
async function copyCareerCode(){let el=$('careerCode');el.focus();el.select();try{await navigator.clipboard.writeText(el.value);toast('Код скопирован')}catch(e){toast('Код выделен. Нажми «Копировать» в меню устройства.')}}
function importCode(){openModal(`<h2>Вставь код сохранения</h2><p>Поддерживаются коды и JSON-файлы из предыдущих версий игры.</p><textarea id="importCodeText" rows="8" placeholder="Вставь код целиком" style="width:100%" spellcheck="false"></textarea><div class="actions">${btn('Отмена','closeModal()')}${btn('Проверить и загрузить','loadCode()',true)}</div>`)}
function loadCode(){let x=decodePacket($('importCodeText').value.trim());if(!x){toast('Не удалось прочитать код. Вставь его целиком.');return}prepareLoad(x)}
async function importSave(file){if(!file)return;if(file.size>20000000){toast('Файл слишком большой');return}try{let x=decodePacket(await file.text());if(!x){toast('Неверный формат или повреждённый файл');return}prepareLoad(x)}catch(e){toast('Не удалось открыть файл. Попробуй вставить код.')}}
async function testStorage(){let raw=JSON.stringify({updatedAt:new Date().toISOString(),test:'AncientManager'}),r=await persist('ancient-manager-storage-test',raw);storageHealth=healthText(r);openModal(`<h2>${r.ok?'Хранилище работает':'Запись запрещена или недоступна'}</h2><p>Хранилище браузера: ${r.local?'запись и чтение успешны':'недоступно'}<br>IndexedDB: ${r.indexed?'запись и чтение успешны':'недоступно'}</p><p>Слоты относятся к конкретному браузеру и адресу сайта. Для переноса и надёжной отдельной копии используй JSON или код.</p><div class="actions">${btn('Закрыть','closeModal()')}${btn('Файл или код','portableSave()',true)}</div>`)}
function savesView(){let backup=readSnapshot('ancient-manager-backup'),previous=readSnapshot(KEY+'-previous'),legacy=readSnapshot('ancient-manager-before-update');return head('ПРОГРЕСС ПОД КОНТРОЛЕМ','Сохранения карьеры','Проверка чтения после записи · 5 слотов · файл и код')+`<section class="panel storage-panel"><h2>${esc(storageHealth)}</h2><p>Игра пробует два хранилища: браузерное и IndexedDB. Сохранение считается успешным только после чтения записанных данных. Слоты доступны на этом устройстве в этом браузере; файл и код можно перенести куда угодно.</p><div class="filters">${btn('Проверить хранилище','testStorage()')}${btn('Скачать файл / скопировать код','portableSave()',true)}${btn('Вставить код','importCode()')}<label class="file-button">Загрузить JSON<input type="file" accept=".json,application/json" onchange="importSave(this.files[0]);this.value=''" aria-label="Импорт сохранения"></label></div></section><div class="cards" style="margin-top:20px">${Array.from({length:5},(_,i)=>{let x=readSnapshot(slotKey(i));return snapshotCard(x,'Слот '+(i+1),btn(x?'Перезаписать':'Сохранить сюда',`askSaveSlot(${i})`,true)+(x?btn('Загрузить',`askLoad('${slotKey(i)}')`)+btn('Удалить',`askDeleteSlot(${i})`):''))}).join('')}${previous?snapshotCard(previous,'Предыдущее автосохранение',btn('Восстановить',`askLoad('${KEY}-previous')`)):''}${backup?snapshotCard(backup,MEMORY_BACKUP?'Резерв · до закрытия вкладки':'Резервная копия',btn('Восстановить',"askLoad('ancient-manager-backup')")):''}${legacy?snapshotCard(legacy,'До обновления',btn('Восстановить',"askLoad('ancient-manager-before-update')")):''}</div>`}
async function boot(){
 $('app').innerHTML='<section class="panel empty"><h2>Восстанавливаем карьеру…</h2><p>Проверяем сохранения и резервные копии.</p></section>';$('advance').disabled=true;
 // Do not write a partially migrated career if startup fails.
 recoveryBlocked=true;await initStorage();
 let raw=STORE_CACHE.get(KEY),current=decodePacket(raw),candidates=[readSnapshot(KEY+'-previous'),readSnapshot('ancient-manager-backup'),...Array.from({length:5},(_,i)=>readSnapshot(slotKey(i)))].filter(Boolean).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt)),loaded=current||candidates[0],unreadable=false;
 if(loaded){S=structuredClone(loaded.state);migrate();if(typeof applyTIRewind==='function')await applyTIRewind(loaded);selectedBracket=S.active?.event??null;tournamentTab=S.active?.phase==='groups'?'groups':'playoffs';page=S.active?.live?'match':'home';render();if(!current)toast('Основная копия недоступна. Карьера восстановлена из резервного сохранения.')}
 else if(raw){unreadable=true;fresh();openModal(`<h2>Старое сохранение не удалось прочитать</h2><p>Игра не перезаписывает его. Можно скачать исходную копию, загрузить JSON или код, либо начать новую карьеру.</p><div class="actions">${btn('Скачать исходное сохранение','downloadStartupSave()')}${btn('Вставить код','importCode()',true)}${btn('Начать новую','allowNewCareer()')}</div>`)}
 else fresh();
 if(!unreadable){recoveryBlocked=false;save();}
 $('advance').disabled=!!S?.practice13||!!S?.active?.autoCoach13;await saveQueue;
}
async function allowNewCareer(){let raw=STORE_CACHE.get(KEY);if(raw)await persist('ancient-manager-unreadable',raw);recoveryBlocked=false;lastAuto='';closeModal();go('home')}

$('advance').onclick=advance;

